-- CarboTrack departmental access upgrade. Run after institutional-schema.sql.
alter table public.organization_members add column if not exists department text;
alter table public.organization_members drop constraint if exists organization_members_role_check;
alter table public.organization_members add constraint organization_members_role_check check(role in('admin','data_manager','viewer','energy_manager','fuel_manager','transport_manager','waste_manager','procurement_manager'));
alter table public.activity_records add column if not exists department text;
create or replace function public.carbotrack_can_submit(org_id uuid, dept text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.organization_members m where m.organization_id=org_id and m.user_id=auth.uid() and (m.role in('admin','data_manager') or (m.role='energy_manager' and dept='energy') or (m.role='fuel_manager' and dept='fuel') or (m.role='transport_manager' and dept='transport') or (m.role='waste_manager' and dept='waste') or (m.role='procurement_manager' and dept='procurement'))); $$;
drop policy if exists activity_insert_managers on public.activity_records;\ndrop policy if exists activity_insert_department on public.activity_records;
drop policy if exists activity_update_managers on public.activity_records;\ndrop policy if exists activity_update_department on public.activity_records;
create policy activity_insert_department on public.activity_records for insert to authenticated with check(public.carbotrack_can_submit(organization_id,department) and entered_by=auth.uid());
create policy activity_update_department on public.activity_records for update to authenticated using(public.carbotrack_can_submit(organization_id,department)) with check(public.carbotrack_can_submit(organization_id,department));
create or replace function public.carbotrack_add_member(p_email text,p_role text,p_department text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare target_id uuid; org_id uuid; begin select organization_id into org_id from public.organization_members where user_id=auth.uid() and role='admin' limit 1; if org_id is null then raise exception 'Only an institution administrator can add staff'; end if; if p_role not in('data_manager','viewer','energy_manager','fuel_manager','transport_manager','waste_manager','procurement_manager') then raise exception 'Invalid staff role'; end if; if (p_role='energy_manager' and p_department<>'energy') or (p_role='fuel_manager' and p_department<>'fuel') or (p_role='transport_manager' and p_department<>'transport') or (p_role='waste_manager' and p_department<>'waste') or (p_role='procurement_manager' and p_department<>'procurement') then raise exception 'Department does not match the selected role'; end if; select id into target_id from auth.users where lower(email)=lower(trim(p_email)) limit 1; if target_id is null then raise exception 'This email has not registered yet. Ask the staff member to create a CarboTrack account first.'; end if; insert into public.organization_members(organization_id,user_id,role,department) values(org_id,target_id,p_role,case when p_role in('energy_manager','fuel_manager','transport_manager','waste_manager','procurement_manager') then p_department else null end) on conflict(organization_id,user_id) do update set role=excluded.role,department=excluded.department; return target_id; end; $$;
grant execute on function public.carbotrack_add_member(text,text,text) to authenticated;
create or replace function public.carbotrack_list_members() returns table(member_id uuid,email text,role text,department text,joined_at timestamptz) language sql stable security definer set search_path=public as $$ select m.user_id,u.email,m.role,m.department,m.created_at from public.organization_members m join auth.users u on u.id=m.user_id where m.organization_id=(select organization_id from public.organization_members where user_id=auth.uid() limit 1) and public.carbotrack_is_member(m.organization_id) order by m.created_at; $$;
grant execute on function public.carbotrack_list_members() to authenticated;